302	    /** A mutable variable declared at the top level of a component.  Like
303	     * StaticBinding it lives in the singleton field of its own inner class,
304	     * but that field holds a MutableFValue cell rather than the value, so that
305	     * reads and writes can go through the current transaction exactly as
306	     * LocalMutableVar and MutableTaskVarCodeGen do, and so that a nested
307	     * code-generation context captures the cell rather than a copy of the
308	     * value.  A separate class rather than a flag on StaticBinding, so that
309	     * assignment to an immutable top-level variable keeps failing.
310	     */
311	    public static class MutableStaticBinding extends NeedsType {
312	
313	        /** Internal name of the variable's declared type, for the cast after
314	         *  reading the cell. */
315	        private final String typeInternalName;
316	
317	        public MutableStaticBinding(IdOrOp id, Type fortressType, String owner, String name,
318	                                    String typeInternalName) {
319	            super(id, fortressType, owner, name, NamingCzar.descFortressMutableFValueInternal);
320	            this.typeInternalName = typeInternalName;
321	        }
322	
323	        private void pushCell(CodeGenMethodVisitor mv) {
324	            mv.visitFieldInsn(Opcodes.GETSTATIC, packageAndClassName, objectFieldName, classDesc);
325	        }
326	
327	        public void pushValue(CodeGenMethodVisitor mv) {
328	            Label atomicEnd = new Label();
329	            Label end = new Label();
330	            mv.visitMethodInsn(Opcodes.INVOKESTATIC,
331	                               "com/sun/fortress/runtimeSystem/BaseTask",
332	                               "inATransaction",
333	                               "()Z");
334	            mv.visitJumpInsn(Opcodes.IFEQ, atomicEnd);
335	            mv.visitMethodInsn(Opcodes.INVOKESTATIC,
336	                               "com/sun/fortress/runtimeSystem/BaseTask",
337	                               "getCurrentTransaction",
338	                               "()Lcom/sun/fortress/runtimeSystem/Transaction;");
339	            pushCell(mv);
340	            mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL,
341	                               "com/sun/fortress/runtimeSystem/Transaction",
342	                               "TXRead",
343	                               "(" + NamingCzar.descFortressMutableFValueInternal + ")" + NamingCzar.descFortressAny);
344	            mv.visitJumpInsn(Opcodes.GOTO, end);
345	            mv.visitLabel(atomicEnd);
346	
347	            pushCell(mv);
348	            mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL,
349	                               "com/sun/fortress/compiler/runtimeValues/MutableFValue",
350	                               "getValue",
351	                               "()" + NamingCzar.descFortressAny);
352	            mv.visitLabel(end);
353	            InstantiatingClassloader.generalizedCastTo(mv, typeInternalName);
354	        }
355	
356	        public void assignValue(CodeGenMethodVisitor mv) {
357	            // The value to assign is already on the stack.
358	            Label atomicEnd = new Label();
359	            Label end = new Label();
360	
361	            mv.visitMethodInsn(Opcodes.INVOKESTATIC,
362	                               "com/sun/fortress/runtimeSystem/BaseTask",
363	                               "inATransaction",
364	                               "()Z");
365	            mv.visitJumpInsn(Opcodes.IFEQ, atomicEnd);
366	            mv.visitMethodInsn(Opcodes.INVOKESTATIC,
367	                               "com/sun/fortress/runtimeSystem/BaseTask",
368	                               "getCurrentTransaction",
369	                               "()Lcom/sun/fortress/runtimeSystem/Transaction;");
370	            mv.visitInsn(Opcodes.SWAP);
371	            pushCell(mv);
372	            mv.visitInsn(Opcodes.SWAP);
373	            mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL,
374	                               "com/sun/fortress/runtimeSystem/Transaction",
375	                               "TXWrite",
376	                               "(" + NamingCzar.descFortressMutableFValueInternal + NamingCzar.descFortressAny + ")V");
377	            mv.visitJumpInsn(Opcodes.GOTO, end);
378	            mv.visitLabel(atomicEnd);
379	
380	            pushCell(mv);
381	            mv.visitInsn(Opcodes.SWAP);
382	            mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL,
383	                               "com/sun/fortress/compiler/runtimeValues/MutableFValue",
384	                               "setValue",
385	                               "(" + NamingCzar.descFortressAny + ")V");
386	            mv.visitLabel(end);
387	        }
388	
389	        public void pushHandle(CodeGenMethodVisitor mv) {
390	            pushCell(mv);
391	        }
392	
393	        public void assignHandle(CodeGenMethodVisitor mv) {
394	            throw new CompilerError(errorMsg("Invalid assignment to the cell of top-level variable ",
395	                                             name, ": ", fortressType));
396	        }
397	
398	        public String toString() {
399	            return "VarCodeGen[MutableStaticBinding] " + name + ":" + fortressType;
400	        }
401	
